import math

def check_n(n):
    D = 2 * n - 1
    if D == 0:
        return "Undefined (D=0)"

    numerator = 3 * (math.factorial(n + 2) + 1)

    if numerator % D == 0:
        return f"Integer (n={n})"
    else:
        return f"Not Integer (n={n})"

# Check the requested values
tests = [3, 5, 6, 8]
results = {n: check_n(n) for n in tests}

print("--- Results for specific tests ---")
for n, result in results.items():
    print(result)

# Check n=0, 1 as well, since they are simple cases
print(check_n(0))
print(check_n(1))

